                        content:
                            "“那无常的命运之神啊，时而令我们欢喜，时而令我们苦痛……”\n“常怀虔诚之心……祂洁白的纺线终会将我们与那众天之天的乐土连缀……”\n少年认真而虔诚地朗读着书本上的词句，对你的出现浑然不觉。",
