                        id: 6201103,
                        content:
                            "“请收下这个。”\n青年的声音在身后响起。他将一件物事交到你手上。\n“它不会发光，所以它不需余烬交换。”\n那是一枚糖果，晶莹而透明，静静地躺在你沾满血污和灰烬的手心里。",
                        speakerName: "深渊行商",
