                        content:
                            "你将它缓缓吞入口中，是野薄荷的味道。它让你前所未有地清醒，你终于找回了一些人的知觉。\n你的脑海里不再只有幽影。你开始想起耸入云端的高塔，想起总是忍不住攀爬的橡子树，想起餐盘上冰凉的奶油，想起庭院里摆荡的秋千。\n那是你活过的证明。",
                        next: 6201105,
